('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00004','Informations générales',4,'Text','Comprendre la nullité lorsqu’aucun texte ne la prévoit expressément, mais que ','Comprendre la nullité lorsqu’aucun texte ne la prévoit expressément, mais que ','{"font_weight_hints":["FontWeight.w900","FontWeight.w500"],"font_size_hints":["21","13.5"]}'::jsonb,true),
