('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00006','1.2 – Les nullités substantielles',6,'_SubTitle','1.2 – Les nullités substantielles','1.2 – Les nullités substantielles','{"font_weight_hints":["FontWeight.w500"],"font_size_hints":["13.5"]}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00007','1.2 – Les nullités substantielles',7,'TextSpan','Les nullités substantielles interviennent lorsque la méconnaissance d’une formalité importante, ','Les nullités substantielles interviennent lorsque la méconnaissance d’une formalité importante, ','{}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00008','1.2 – Les nullités substantielles',8,'TextSpan','prévue par une disposition de procédure pénale, porte atteinte aux intérêts de la partie qu’elle concerne. ','prévue par une disposition de procédure pénale, porte atteinte aux intérêts de la partie qu’elle concerne. ','{}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00009','1.2 – Les nullités substantielles',9,'string','À la différence des nullités textuelles, aucun texte ne prévoit nécessairement, de manière expresse, la nullité pour l’acte vicié.','À la différence des nullités textuelles, aucun texte ne prévoit nécessairement, de manière expresse, la nullité pour l’acte vicié.','{"color_hints":["Colors.red"],"font_weight_hints":["FontWeight.w800"]}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00010','1.2 – Les nullités substantielles',10,'TextSpan','L’','L’','{"color_hints":["Colors.red"],"font_weight_hints":["FontWeight.w800"]}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00011','1.2 – Les nullités substantielles',11,'TextSpan','Article 171 du Code de Procédure Pénale','Article 171 du Code de Procédure Pénale','{"color_hints":["Colors.red"],"font_weight_hints":["FontWeight.w800"]}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00012','1.2 – Les nullités substantielles',12,'TextSpan',' donne une définition centrale de cette notion : « Il y a nullité lorsque la méconnaissance d’une formalité substantielle, ',' donne une définition centrale de cette notion : « Il y a nullité lorsque la méconnaissance d’une formalité substantielle, ','{"color_hints":["Colors.red"],"font_weight_hints":["FontWeight.w800"]}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00013','1.2 – Les nullités substantielles',13,'TextSpan','prévue par une disposition du présent code ou par toute autre disposition de procédure pénale, a porté atteinte aux intérêts de la partie qu’elle concerne. »','prévue par une disposition du présent code ou par toute autre disposition de procédure pénale, a porté atteinte aux intérêts de la partie qu’elle concerne. »','{"color_hints":["Colors.white","const Color(0xFF0D47A1)"]}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00014','Définition et critère de la nullité substantielle',14,'title','Définition et critère de la nullité substantielle','Définition et critère de la nullité substantielle','{"color_hints":["Colors.white","const Color(0xFF0D47A1)"]}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00015','Définition et critère de la nullité substantielle',15,'_Paragraph','Selon le système des nullités substantielles, la nullité peut être prononcée même si la loi est silencieuse sur la sanction. ','Selon le système des nullités substantielles, la nullité peut être prononcée même si la loi est silencieuse sur la sanction. ','{"color_hints":["Colors.white","const Color(0xFF0D47A1)"]}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00016','Définition et critère de la nullité substantielle',16,'_Paragraph','L’irrégularité n’est pas forcément assortie d’une mention « à peine de nullité », mais son importance impose qu’elle soit sanctionnée ','L’irrégularité n’est pas forcément assortie d’une mention « à peine de nullité », mais son importance impose qu’elle soit sanctionnée ','{}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00017','Définition et critère de la nullité substantielle',17,'string','lorsqu’elle porte atteinte aux droits fondamentaux des parties.','lorsqu’elle porte atteinte aux droits fondamentaux des parties.','{}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00018','Définition et critère de la nullité substantielle',18,'TextSpan','La jurisprudence de la chambre criminelle de la Cour de cassation exige, pour prononcer une nullité substantielle, ','La jurisprudence de la chambre criminelle de la Cour de cassation exige, pour prononcer une nullité substantielle, ','{}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00019','Définition et critère de la nullité substantielle',19,'TextSpan','qu’il y ait : ','qu’il y ait : ','{}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00020','Définition et critère de la nullité substantielle',20,'string','Une atteinte grave aux droits de la défense (droit à un avocat, droit de se taire, droit à l’information, etc.).','Une atteinte grave aux droits de la défense (droit à un avocat, droit de se taire, droit à l’information, etc.).','{}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00021','Définition et critère de la nullité substantielle',21,'string','Ou un vice fondamental dans la recherche et l’établissement de la vérité (actes d’enquête ou d’instruction déloyaux, irréguliers ou trompeurs).','Ou un vice fondamental dans la recherche et l’établissement de la vérité (actes d’enquête ou d’instruction déloyaux, irréguliers ou trompeurs).','{"color_hints":["Colors.white","const Color(0xFF0D47A1)"]}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00022','Exemples typiques de nullités substantielles',22,'title','Exemples typiques de nullités substantielles','Exemples typiques de nullités substantielles','{"color_hints":["Colors.white","const Color(0xFF0D47A1)"]}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00023','Exemples typiques de nullités substantielles',23,'TextSpan','La circulaire du ministre de la Justice du 24 août 1991 rappelle que la suppression de certaines nullités textuelles, ','La circulaire du ministre de la Justice du 24 août 1991 rappelle que la suppression de certaines nullités textuelles, ','{"color_hints":["Colors.white","const Color(0xFF0D47A1)"]}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00024','Exemples typiques de nullités substantielles',24,'TextSpan','notamment en matière de garde à vue, ne signifie pas que les garanties prévues par la loi sont dépourvues de sanction. ','notamment en matière de garde à vue, ne signifie pas que les garanties prévues par la loi sont dépourvues de sanction. ','{}'::jsonb,true),
('lib/content/pa_scolarite/procedure_penale_pages/pp_nullites_substantielles_page.dart','f00025','Exemples typiques de nullités substantielles',25,'string','Elles peuvent être protégées par la nullité substantielle lorsque leur violation porte atteinte aux droits de la défense.','Elles peuvent être protégées par la nullité substantielle lorsque leur violation porte atteinte aux droits de la défense.','{}'::jsonb,true),
